#include <sycl/sycl.hpp>

#include "chooseDevice.h"

namespace cms::sycltools {


// The following comment is generated by an LLM. 
/**
 * @brief Discovers available SYCL devices and returns them in a vector.
 * 
 * This function retrieves CPU and GPU devices, removes duplicates with lower driver versions,
 * and combines them into a single vector.
 * 
 * @return A vector of unique SYCL devices.
 */  static std::vector<sycl::device> discoverDevices() {
    std::vector<sycl::device> temp;
    std::vector<sycl::device> cpus = sycl::device::get_devices(sycl::info::device_type::cpu);
    std::vector<sycl::device> gpus = sycl::device::get_devices(sycl::info::device_type::gpu);
    for (auto it = cpus.begin(); it != cpus.end(); it++) {
      if (it + 1 == cpus.end()) {
        break;
      }
      if ((*it).get_info<sycl::info::device::name>() == (*(it + 1)).get_info<sycl::info::device::name>() and
          (*it).get_backend() == (*(it + 1)).get_backend() and
          (*(it + 1)).get_info<sycl::info::device::driver_version>() <
              (*it).get_info<sycl::info::device::driver_version>()) {
        cpus.erase(it + 1);
      }
    }
    temp.insert(temp.end(), cpus.begin(), cpus.end());

    for (auto it = gpus.begin(); it != gpus.end(); it++) {
      if (it + 1 == gpus.end()) {
        break;
      }
      if ((*it).get_info<sycl::info::device::name>() == (*(it + 1)).get_info<sycl::info::device::name>() and
          (*it).get_backend() == (*(it + 1)).get_backend() and
          (*(it + 1)).get_info<sycl::info::device::driver_version>() <
              (*it).get_info<sycl::info::device::driver_version>()) {
        gpus.erase(it + 1);
      }
    }
    temp.insert(temp.end(), gpus.begin(), gpus.end());
    return temp;
  }


// The following comment is generated by an LLM. 
/**
 * @brief Returns a list of available SYCL devices
 * @param verbose If true prints discovered devices to standard error stream
 * @return A constant reference to a vector of SYCL devices */  std::vector<sycl::device> const& enumerateDevices(bool verbose) {
    static const std::vector<sycl::device> devices = discoverDevices();

    if (verbose) {
      if (devices.size() == 0) {
        std::cerr << "Found 0 SYCL devices\n";
      } else if (devices.size() == 1) {
        std::cerr << "Found 1 SYCL device:\n";
      } else {
        std::cerr << "Found " << devices.size() << " SYCL devices:\n";
      }
      for (auto const& device : devices)
        std::cerr << "  - " << device.get_backend() << ' ' << device.get_info<sycl::info::device::name>() << " ["
                  << device.get_info<sycl::info::device::driver_version>() << "]" << std::endl;
      std::cerr << std::endl;
    }
    return devices;
  }


// The following comment is generated by an LLM. 
/**
 * Returns a vector of unique SYCL platforms discovered from the available devices
 */  static std::vector<sycl::platform> discoverPlatforms() {
    std::vector<sycl::platform> temp;
    auto const& devices = enumerateDevices();

    for (auto dev : devices) {
      if (std::find(temp.begin(), temp.end(), dev.get_platform()) == temp.end()) {
        temp.emplace_back(dev.get_platform());
      }
    }

    return temp;
  }


// The following comment is generated by an LLM. 
/**
 * Returns a list of available SYCL platforms
 * @param verbose flag to enable detailed output
 * @return vector of SYCL platforms
 */  std::vector<sycl::platform> const& enumeratePlatforms(bool verbose) {
    static const std::vector<sycl::platform> platforms = discoverPlatforms();

    if (verbose) {
      std::cerr << "Found " << platforms.size() << " SYCL Platforms:" << std::endl;
      for (auto const& plt : platforms)
        std::cerr << "  - " << plt.get_info<sycl::info::platform::name>() << std::endl;
    }
    return platforms;
  }


// The following comment is generated by an LLM. 
/**
 * @brief Selects a SYCL device based on the EDM stream ID and verbosity level
 * @param id The EDM stream ID used to determine the device selection
 * @param verbose Flag indicating whether to print device selection details
 * @return The chosen SYCL device object
 */  sycl::device chooseDevice(edm::StreamID id, bool verbose) {
    auto const& devices = enumerateDevices();
    auto const& device = devices[id % devices.size()];
    if (verbose) {
      std::ostringstream out;
      out << "EDM stream " << id << " offload to " << device.get_info<sycl::info::device::name>()
          << " on backend " << device.get_backend() << '\n';
      std::cerr << out.str();
    }
    return device;
  }
}  // namespace cms::sycltools
